head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst90005";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — detail2

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst90005.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_if_42", fn: function(){ return ((((dma_detail1.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "detail1.acntclsMmdd1"); })())) && typeof ((dma_detail1.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "detail1.acntclsMmdd1"); })())).getRowCount === 'function' ? ((dma_detail1.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "detail1.acntclsMmdd1"); })())).getRowCount() : ((((dma_detail1.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "detail1.acntclsMmdd1"); })())) == null) ? 0 : (((dma_detail1.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "detail1.acntclsMmdd1"); })())).length || 0))) > 0); } }, { id: "c_when_58_txt", fn: function(){ return ((dma_detail1.get("hpage") ?? (() => { throw new Error("unresolved:" + "detail1.hpage"); })()) === '-' || (dma_detail1.get("hpage") ?? (() => { throw new Error("unresolved:" + "detail1.hpage"); })()) === ''); } }, { id: "c_otherwise_59", fn: function(){ return (!(((dma_detail1.get("hpage") ?? (() => { throw new Error("unresolved:" + "detail1.hpage"); })()) === '-' || (dma_detail1.get("hpage") ?? (() => { throw new Error("unresolved:" + "detail1.hpage"); })()) === ''))); } }, { id: "c_when_80_txt", fn: function(){ return (!(String(((dma_detail3.get("data5") ?? (() => { throw new Error("unresolved:" + "detail3.data5"); })())) == null ? '' : ((dma_detail3.get("data5") ?? (() => { throw new Error("unresolved:" + "detail3.data5"); })()))).length === 0)); } }, { id: "c_otherwise_81", fn: function(){ return (!((!(String(((dma_detail3.get("data5") ?? (() => { throw new Error("unresolved:" + "detail3.data5"); })())) == null ? '' : ((dma_detail3.get("data5") ?? (() => { throw new Error("unresolved:" + "detail3.data5"); })()))).length === 0)))); } }, { id: "c_when_86_txt", fn: function(){ return (!(String(((dma_detail3.get("data6") ?? (() => { throw new Error("unresolved:" + "detail3.data6"); })())) == null ? '' : ((dma_detail3.get("data6") ?? (() => { throw new Error("unresolved:" + "detail3.data6"); })()))).length === 0)); } }, { id: "c_otherwise_87", fn: function(){ return (!((!(String(((dma_detail3.get("data6") ?? (() => { throw new Error("unresolved:" + "detail3.data6"); })())) == null ? '' : ((dma_detail3.get("data6") ?? (() => { throw new Error("unresolved:" + "detail3.data6"); })()))).length === 0)))); } }, { id: "c_when_92_txt", fn: function(){ return (!(String(((dma_detail3.get("data7") ?? (() => { throw new Error("unresolved:" + "detail3.data7"); })())) == null ? '' : ((dma_detail3.get("data7") ?? (() => { throw new Error("unresolved:" + "detail3.data7"); })()))).length === 0)); } }, { id: "c_otherwise_93", fn: function(){ return (!((!(String(((dma_detail3.get("data7") ?? (() => { throw new Error("unresolved:" + "detail3.data7"); })())) == null ? '' : ((dma_detail3.get("data7") ?? (() => { throw new Error("unresolved:" + "detail3.data7"); })()))).length === 0)))); } }, { id: "c_when_98_txt", fn: function(){ return (!(String(((dma_detail3.get("data8") ?? (() => { throw new Error("unresolved:" + "detail3.data8"); })())) == null ? '' : ((dma_detail3.get("data8") ?? (() => { throw new Error("unresolved:" + "detail3.data8"); })()))).length === 0)); } }, { id: "c_otherwise_99", fn: function(){ return (!((!(String(((dma_detail3.get("data8") ?? (() => { throw new Error("unresolved:" + "detail3.data8"); })())) == null ? '' : ((dma_detail3.get("data8") ?? (() => { throw new Error("unresolved:" + "detail3.data8"); })()))).length === 0)))); } }, { id: "c_when_106_txt", fn: function(){ return (!(String(((dma_detail3.get("data1") ?? (() => { throw new Error("unresolved:" + "detail3.data1"); })())) == null ? '' : ((dma_detail3.get("data1") ?? (() => { throw new Error("unresolved:" + "detail3.data1"); })()))).length === 0)); } }, { id: "c_otherwise_107", fn: function(){ return (!((!(String(((dma_detail3.get("data1") ?? (() => { throw new Error("unresolved:" + "detail3.data1"); })())) == null ? '' : ((dma_detail3.get("data1") ?? (() => { throw new Error("unresolved:" + "detail3.data1"); })()))).length === 0)))); } }, { id: "c_when_113_txt", fn: function(){ return (!(String(((dma_detail3.get("data2") ?? (() => { throw new Error("unresolved:" + "detail3.data2"); })())) == null ? '' : ((dma_detail3.get("data2") ?? (() => { throw new Error("unresolved:" + "detail3.data2"); })()))).length === 0)); } }, { id: "c_otherwise_114", fn: function(){ return (!((!(String(((dma_detail3.get("data2") ?? (() => { throw new Error("unresolved:" + "detail3.data2"); })())) == null ? '' : ((dma_detail3.get("data2") ?? (() => { throw new Error("unresolved:" + "detail3.data2"); })()))).length === 0)))); } }, { id: "c_when_119_txt", fn: function(){ return (!(String(((dma_detail3.get("data4") ?? (() => { throw new Error("unresolved:" + "detail3.data4"); })())) == null ? '' : ((dma_detail3.get("data4") ?? (() => { throw new Error("unresolved:" + "detail3.data4"); })()))).length === 0)); } }, { id: "c_otherwise_120", fn: function(){ return (!((!(String(((dma_detail3.get("data4") ?? (() => { throw new Error("unresolved:" + "detail3.data4"); })())) == null ? '' : ((dma_detail3.get("data4") ?? (() => { throw new Error("unresolved:" + "detail3.data4"); })()))).length === 0)))); } }, { id: "c_when_126_txt", fn: function(){ return (!(String(((dma_detail3.get("data3") ?? (() => { throw new Error("unresolved:" + "detail3.data3"); })())) == null ? '' : ((dma_detail3.get("data3") ?? (() => { throw new Error("unresolved:" + "detail3.data3"); })()))).length === 0)); } }, { id: "c_otherwise_127", fn: function(){ return (!((!(String(((dma_detail3.get("data3") ?? (() => { throw new Error("unresolved:" + "detail3.data3"); })())) == null ? '' : ((dma_detail3.get("data3") ?? (() => { throw new Error("unresolved:" + "detail3.data3"); })()))).length === 0)))); } }, { id: "c_when_133_txt", fn: function(){ return (!(String(((dma_detail3.get("data10") ?? (() => { throw new Error("unresolved:" + "detail3.data10"); })())) == null ? '' : ((dma_detail3.get("data10") ?? (() => { throw new Error("unresolved:" + "detail3.data10"); })()))).length === 0)); } }, { id: "c_otherwise_134", fn: function(){ return (!((!(String(((dma_detail3.get("data10") ?? (() => { throw new Error("unresolved:" + "detail3.data10"); })())) == null ? '' : ((dma_detail3.get("data10") ?? (() => { throw new Error("unresolved:" + "detail3.data10"); })()))).length === 0)))); } }, { id: "c_when_139_txt", fn: function(){ return (!(String(((dma_detail3.get("data11") ?? (() => { throw new Error("unresolved:" + "detail3.data11"); })())) == null ? '' : ((dma_detail3.get("data11") ?? (() => { throw new Error("unresolved:" + "detail3.data11"); })()))).length === 0)); } }, { id: "c_otherwise_140", fn: function(){ return (!((!(String(((dma_detail3.get("data11") ?? (() => { throw new Error("unresolved:" + "detail3.data11"); })())) == null ? '' : ((dma_detail3.get("data11") ?? (() => { throw new Error("unresolved:" + "detail3.data11"); })()))).length === 0)))); } }, { id: "c_when_145_txt", fn: function(){ return (!(String(((dma_detail3.get("data12") ?? (() => { throw new Error("unresolved:" + "detail3.data12"); })())) == null ? '' : ((dma_detail3.get("data12") ?? (() => { throw new Error("unresolved:" + "detail3.data12"); })()))).length === 0)); } }, { id: "c_otherwise_146", fn: function(){ return (!((!(String(((dma_detail3.get("data12") ?? (() => { throw new Error("unresolved:" + "detail3.data12"); })())) == null ? '' : ((dma_detail3.get("data12") ?? (() => { throw new Error("unresolved:" + "detail3.data12"); })()))).length === 0)))); } }, { id: "c_when_151_txt", fn: function(){ return (!(String(((dma_detail3.get("data13") ?? (() => { throw new Error("unresolved:" + "detail3.data13"); })())) == null ? '' : ((dma_detail3.get("data13") ?? (() => { throw new Error("unresolved:" + "detail3.data13"); })()))).length === 0)); } }, { id: "c_otherwise_152", fn: function(){ return (!((!(String(((dma_detail3.get("data13") ?? (() => { throw new Error("unresolved:" + "detail3.data13"); })())) == null ? '' : ((dma_detail3.get("data13") ?? (() => { throw new Error("unresolved:" + "detail3.data13"); })()))).length === 0)))); } }, { id: "if_detail2", fn: function(){ return (!(String(((dma_pageContext.get("detail2") ?? "")) == null ? '' : ((dma_pageContext.get("detail2") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String(dma_detail1.get("comNm")).split("&").join("&")); } },
        { childId: "__rb1", fn: function () { return String(String(dma_detail1.get("comEngNm")).split("&").join("&")); } },
        { childId: "__rb2", fn: function () { return String(String(dma_detail1.get("comAbbrv")).split("&").join("&")); } },
        { childId: "__rb3", fn: function () { return String(String(dma_detail1.get("comEngAbbrv")).split("&").join("&")); } },
        { childId: "__rb12", fn: function () { return String(dma_detail1.get("acntclsMmdd1")); } },
        { childId: "btn_homePagePoup", fn: function () { return String(dma_detail1.get("hpage")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90005.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_homePagePoup_onclick
 * @description btn_homePagePoup 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_homePagePoup_onclick = function(e){
    try {
        scwin.homePagePoup('' + dma_detail1.get("hpage") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90005.btn_homePagePoup_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name homePagePoup
 * @description home Page Poup 처리
 * @param {String} url url
 * @returns {void}
 * @hidden N
 */
scwin.homePagePoup = function (url) {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: 'popup' }, {});
};
